import { CanvasCore } from './CanvasCore';
import { Core } from './Core/Core';
export class AppGridSystem {
    canvasCore: CanvasCore;
    core: Core;

    constructor(id: string = 'SandBox') {
        this.core = new Core();
        this.canvasCore = new CanvasCore(id);
        this.BindEvent();
        this.BindRenderer();
    }
    BindEvent() {
        this.canvasCore.MouseDown = (e: MouseEvent) => this.core.MouseDown(e);
        this.canvasCore.MouseMove = (e: MouseEvent) => this.core.MouseMove(e);
        this.canvasCore.MouseUp = (e: MouseEvent) => this.core.MouseUp(e);
    }
    BindRenderer() {
        this.canvasCore.Render = (ctx: CanvasRenderingContext2D) => this.core.Render(ctx);
    }
    public destroy() {
        this.canvasCore.destroy();
    }
}


export class Solution {
    public divHost: HTMLElement;

    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        new AppGridSystem(id)
    }
    public destroy() {
        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}